<section class="mt-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 fw-bold mb-1">Blocos da nota</h2><p class="text-muted small mb-0">Arraste pela ordem usando os controles ou adicione um novo bloco.</p></div><button class="btn btn-outline-primary" type="button" id="add-block"><i class="bi bi-plus-lg me-1"></i>Adicionar bloco</button></div><div id="blocks" class="d-flex flex-column gap-3"><?php foreach ($blocks as $block): ?><div class="card border-0 shadow-sm note-block"><div class="card-body p-3"><div class="d-flex align-items-center gap-2 mb-3"><span class="text-muted"><i class="bi bi-grip-vertical"></i></span><select name="blocos_tipo[]" class="form-select form-select-sm block-type"><option value="texto" <?= ($block['tipo_bloco'] ?? '') === 'texto' ? 'selected' : '' ?>>Texto</option><option value="codigo" <?= ($block['tipo_bloco'] ?? '') === 'codigo' ? 'selected' : '' ?>>Código</option><option value="imagem" <?= ($block['tipo_bloco'] ?? '') === 'imagem' ? 'selected' : '' ?>>Imagem</option><option value="lista" <?= ($block['tipo_bloco'] ?? '') === 'lista' ? 'selected' : '' ?>>Lista</option><option value="equacao" <?= ($block['tipo_bloco'] ?? '') === 'equacao' ? 'selected' : '' ?>>Equação</option></select><button type="button" class="btn btn-sm btn-light move-up" aria-label="Mover bloco para cima"><i class="bi bi-arrow-up"></i></button><button type="button" class="btn btn-sm btn-light move-down" aria-label="Mover bloco para baixo"><i class="bi bi-arrow-down"></i></button><button type="button" class="btn btn-sm btn-outline-danger remove-block" aria-label="Remover bloco"><i class="bi bi-trash"></i></button></div><textarea class="form-control block-content" name="blocos_conteudo[]" rows="4" placeholder="Conteúdo do bloco"><?= htmlspecialchars((string) ($block['conteudo'] ?? ''), ENT_QUOTES, 'UTF-8') ?></textarea></div></div><?php endforeach; ?></div></section></div>
<aside class="col-12 col-xl-4"><section class="card border-0 shadow-sm"><div class="card-body p-4"><label class="form-label fw-semibold">Disciplina</label><select name="disciplina_id" class="form-select mb-4"><option value="">Sem disciplina</option><?php foreach ($disciplines as $discipline): ?><option value="<?= htmlspecialchars((string) $discipline['id'], ENT_QUOTES, 'UTF-8') ?>" <?= (($note['disciplina_id'] ?? '') === $discipline['id']) ? 'selected' : '' ?>><?= htmlspecialchars((string) $discipline['nome'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><?php if ($isEditing): ?><div class="small text-muted border-top pt-3 mb-4"><div>Criada: <?= date('d/m/Y H:i', strtotime($note['criado_em'])) ?></div><div>Atualizada: <?= date('d/m/Y H:i', strtotime($note['atualizado_em'])) ?></div></div><?php endif; ?><button class="btn btn-primary w-100" type="submit"><i class="bi bi-check-lg me-1"></i><?= $isEditing ? 'Salvar alterações' : 'Criar nota' ?></button></div></section><?php if ($isEditing): ?><button class="btn btn-outline-danger w-100 mt-3" type="submit" form="delete-note-form"><i class="bi bi-trash me-1"></i>Excluir nota</button><?php endif; ?></aside></div></form>
