</main></div></div><?php require dirname(__DIR__) . '/layouts/mobile-navigation.php'; ?>
<template id="block-template"><div class="card border-0 shadow-sm note-block"><div class="card-body p-3"><div class="d-flex align-items-center gap-2 mb-3"><span class="text-muted"><i class="bi bi-grip-vertical"></i></span><select name="blocos_tipo[]" class="form-select form-select-sm block-type"><option value="texto">Texto</option><option value="codigo">Código</option><option value="imagem">Imagem</option><option value="lista">Lista</option><option value="equacao">Equação</option></select><button type="button" class="btn btn-sm btn-light move-up" aria-label="Mover bloco para cima"><i class="bi bi-arrow-up"></i></button><button type="button" class="btn btn-sm btn-light move-down" aria-label="Mover bloco para baixo"><i class="bi bi-arrow-down"></i></button><button type="button" class="btn btn-sm btn-outline-danger remove-block" aria-label="Remover bloco"><i class="bi bi-trash"></i></button></div><textarea class="form-control block-content" name="blocos_conteudo[]" rows="4" placeholder="Conteúdo do bloco"></textarea></div></div></template>
<script>document.addEventListener('DOMContentLoaded',()=>{const blocks=document.getElementById('blocks'),template=document.getElementById('block-template');function bind(block){block.querySelector('.remove-block').addEventListener('click',()=>block.remove());block.querySelector('.move-up').addEventListener('click',()=>{const prev=block.previousElementSibling;if(prev) blocks.insertBefore(block,prev)});block.querySelector('.move-down').addEventListener('click',()=>{const next=block.nextElementSibling;if(next) blocks.insertBefore(next,block)});}blocks.querySelectorAll('.note-block').forEach(bind);document.getElementById('add-block').addEventListener('click',()=>{const block=template.content.firstElementChild.cloneNode(true);bind(block);blocks.append(block);block.querySelector('textarea').focus();});});</script>
